#include <stdlib.h>

int main() {
    int n, k;
    if (scanf("%d %d", &n, &k) != 2) return 0;
    k %= n;
    long long *nums = malloc(n * sizeof(long long));
    long long *res = malloc(n * sizeof(long long));
    for (int i = 0; i < n; i++) scanf("%lld", &nums[i]);
    for (int i = 0; i < n; i++) res[(i + k) % n] = nums[i];
    for (int i = 0; i < n; i++) printf("%lld%s", res[i], i == n - 1 ? "\n" : " ");
    free(nums);
    free(res);
    return 0;
}
